func genHyperNovice_withUltimate(in FormulaInput, v_rawRatio float64, v_ultimateMultiplier float64, v_angel string) float64 {
	if !in.Active(v_angel) {
		return math.Floor(v_rawRatio)
	}
	return math.Floor((math.Floor(v_rawRatio) * v_ultimateMultiplier))
}
func genHyperNovice_withPassiveBonus(in FormulaInput, v_rawRatio float64, v_passiveBonusPercent float64, v_ultimateMultiplier float64, v_angel string) float64 {
	return genHyperNovice_withUltimate(in, math.Floor((math.Floor(v_rawRatio) * (1 + (v_passiveBonusPercent / 100)))), v_ultimateMultiplier, v_angel)
}
func genSorcerer_isSummon(in FormulaInput, v_spirit float64) float64 {
	if float64(in.ActiveLv("_ElementalMaster_spirit")) != 0 {
		return b2f(false)
	}
	return b2f((float64(in.ActiveLv("_Sorcerer_Elemental_Spirit")) == v_spirit))
}
func genSura_asuraSpiritFactor(in FormulaInput) float64 {
	return tern((float64(in.ActiveLv("Total Spirit")) >= 6), 2, 1)
}
func genRebalance_crystalFactor(in FormulaInput, v_shard float64) float64 {
	switch float64(in.ActiveLv("Climax")) {
	case 3:
		return tern((v_shard == 1), 1.5, 1)
	case 4:
		return tern((v_shard == 1), 0.5, 2.5)
	default:
		return 1
	}
}
func genRebalance_elementalRatio(in FormulaInput, v_spirit float64, v_field bool) float64 {
	v_summoned := (float64(in.ActiveLv("_ElementalMaster_spirit")) == v_spirit)
	_ = v_summoned
	return tern(v_field, (((500 + (float64(in.Lv) * tern(v_summoned, 1050, 650))) + (in.T(SPL) * tern(v_summoned, 7, 5))) * float64(in.BaseLv) / 100), (((tern(v_summoned, 5400, 400) + (float64(in.Lv) * tern(v_summoned, 1800, 1550))) + (in.T(SPL) * tern(v_summoned, 10, 5))) * float64(in.BaseLv) / 100))
}
func genRebalance_hyper(in FormulaInput, v_ratio float64, v_magic bool, v_ultimate float64, v_passiveMultiplier float64, v_passiveFlat float64) float64 {
	v_level := float64(float64(in.LearnName(ternS(v_magic, "Self Study Sorcery", "Self Study Tactics"))))
	_ = v_level
	v_passive := float64(tern((v_level > 0), ((v_level * v_passiveMultiplier) + v_passiveFlat), 0))
	_ = v_passive
	return math.Floor((math.Floor((math.Floor((v_ratio * float64(in.BaseLv) / 100)) * (1 + (v_passive / 100)))) * tern(in.Active(ternS(v_magic, "Angel of Magic", "Angel of Power")), v_ultimate, 1)))
}
func genRebalance_aimed(in FormulaInput, v_base float64, v_perLevel float64, v_perAim float64, v_trait float64) float64 {
	return (((v_base + (float64(in.Lv) * (v_perLevel + (float64(in.ActiveLv("_NightWatch_Aiming Count")) * v_perAim)))) + (in.T(CON) * v_trait)) * float64(in.BaseLv) / 100)
}
func genRebalance_grenade(in FormulaInput, v_base float64, v_perLevel float64, v_mastery float64, v_trait float64) float64 {
	return ((((v_base + (float64(in.Lv) * v_perLevel)) + (float64(in.LearnName("Grenade Mastery")) * v_mastery)) + (in.T(CON) * v_trait)) * float64(in.BaseLv) / 100)
}
func genRebalance_celestial(in FormulaInput, v_base float64, v_perLevel float64, v_mastery float64, v_trait float64) float64 {
	return (((v_base + (float64(in.Lv) * (v_perLevel + (float64(in.LearnName("Sky Mastery")) * v_mastery)))) + (in.T(POW) * v_trait)) * float64(in.BaseLv) / 100)
}
func genRebalance_skyState(in FormulaInput, v_value float64) float64 {
	return b2f(containsF([]float64{v_value, 7}, float64(in.ActiveLv("_SkyEmperor_Celestial_Space"))))
}
func genRebalance_mandala(in FormulaInput) float64 {
	return b2f((in.Active("_SoulAscetic_Mandala") || (float64(in.ActiveLv("_SoulAscetic_Blessing")) == 5)))
}
func genRebalance_talisman(in FormulaInput, v_base float64, v_perLevel float64) float64 {
	return (((v_base + (float64(in.Lv) * (v_perLevel + (float64(in.LearnName("Talisman Mastery")) * 15)))) + (in.T(SPL) * 5)) * float64(in.BaseLv) / 100)
}
func genRebalance_creature(in FormulaInput, v_base float64, v_communeBase float64, v_perLevel float64, v_communeLevel float64, v_mastery float64, v_communeMastery float64, v_magic bool) float64 {
	v_commune := (float64(in.LearnName(ternS(v_magic, "Commune with Hyunrok", "Commune with Chulho"))) > 0)
	_ = v_commune
	return ((((tern(v_commune, v_communeBase, v_base) + (float64(in.Lv) * tern(v_commune, v_communeLevel, v_perLevel))) + (float64(in.LearnName("Mystical Creature Mastery")) * tern(v_commune, v_communeMastery, v_mastery))) + (tern(v_magic, in.T(SPL), in.T(POW)) * 5)) * float64(in.BaseLv) / 100)
}
func genRebalance_trapRatio(in FormulaInput) float64 {
	return ((((float64(in.Lv) * 850) + (in.T(CON) * 5)) * float64(in.BaseLv) / 100) * (1 + (0.2 * float64(in.LearnName("Advanced Trap")))))
}
